/** @param {NS} ns */
export async function main(ns) {
  const home = 'home';
  const visited = new Set();
  const allServers = [];
  const queue = [home];

  // BFS to find all reachable servers
  while (queue.length > 0) {
    const current = queue.shift();
    if (visited.has(current)) continue;
    visited.add(current);
    if (current !== home) allServers.push(current);

    const neighbors = ns.scan(current);
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) queue.push(neighbor);
    }
  }

  // Gather server data
  const servers = [];
  for (const srv of allServers) {
    const hackLvl = ns.getServerRequiredHackingLevel(srv);
    const maxMoney = ns.getServerMaxMoney(srv);
    const curMoney = ns.getServerMoneyAvailable(srv);
    const minSec = ns.getServerMinSecurityLevel(srv);
    const curSec = ns.getServerSecurityLevel(srv);
    const hasRoot = ns.hasRootAccess(srv);
    const ports = ns.getServerNumPortsRequired(srv);

    servers.push({
      name: srv,
      hackLvl,
      maxMoney,
      curMoney,
      minSec,
      curSec,
      hasRoot,
      ports
    });
  }

  // Sort by max money descending, take top 10
  servers.sort((a, b) => b.maxMoney - a.maxMoney);
  const top10 = servers.slice(0, 10);

  // Print header with player info
  const myHackLvl = ns.getHackingLevel();
  const homeRam = ns.getServerMaxRam(home);
  ns.tprint(`=== RECONNAISSANCE ===`);
  ns.tprint(`Player Hacking Level: ${myHackLvl}`);
  ns.tprint(`Home RAM: ${homeRam} GB`);
  ns.tprint(`\nTop 10 Targets by Max Money:`);
  ns.tprint(`Host | HackLvl | MaxMoney | CurMoney | MinSec | CurSec | Root | Ports`);
  ns.tprint(`----+----------+----------+----------+--------+--------+------+-------`);

  // Print each target
  for (const s of top10) {
    const root = s.hasRoot ? 'Y' : 'N';
    const maxM = ns.formatNumber(s.maxMoney, 1, 1e9);
    const curM = ns.formatNumber(s.curMoney, 1, 1e9);
    ns.tprint(`${s.name.padEnd(12)} | ${String(s.hackLvl).padStart(7)} | ${maxM.padStart(8)} | ${curM.padStart(8)} | ${s.minSec.toFixed(1).padStart(6)} | ${s.curSec.toFixed(1).padStart(6)} | ${root} | ${s.ports}`);
  }

  ns.tprint(`\nTotal reachable servers: ${allServers.length}`);
}

/** @param {NS} ns */
export async function main(ns) {
  const cheap = 50;
  const recheck_interval = 60000;
  let last_recheck = 0;
  let target = null;
  let hack_count = 0, grow_count = 0, weaken_count = 0;
  let eval_count = 0;

  async function find_best_target() {
    const visited = new Set();
    const queue = ['home'];
    let best = null;
    let best_score = -1;

    while (queue.length > 0) {
      const srv = queue.shift();
      if (visited.has(srv)) continue;
      visited.add(srv);

      const peers = ns.scan(srv);
      for (const peer of peers) {
        if (!visited.has(peer)) queue.push(peer);
      }

      const has_root = ns.hasRootAccess(srv);
      if (!has_root) continue;

      const max_money = ns.getServerMaxMoney(srv);
      if (max_money <= 0) continue;

      const req_hack = ns.getServerRequiredHackingLevel(srv);
      const cur_hack = ns.getHackingLevel();
      if (req_hack > cur_hack) continue;

      const weaken_time = ns.getWeakenTime(srv);
      const score = (max_money / 1e9) - (weaken_time / 1e6);

      if (score > best_score) {
        best_score = score;
        best = srv;
      }
    }
    eval_count++;
    return best;
  }

  while (true) {
    const now = Date.now();
    if (!target || now - last_recheck > recheck_interval) {
      target = await find_best_target();
      last_recheck = now;
      if (target) ns.tprint(`TARGET: ${target}`);
    }

    if (!target) {
      await ns.asleep(5000);
      continue;
    }

    const sec = ns.getServerSecurityLevel(target);
    const min_sec = ns.getServerMinSecurityLevel(target);
    const money = ns.getServerMoneyAvailable(target);
    const max_money = ns.getServerMaxMoney(target);

    if (sec > min_sec + 5) {
      await ns.weaken(target);
      weaken_count++;
    } else if (money < max_money * 0.9) {
      await ns.grow(target);
      grow_count++;
    } else {
      await ns.hack(target);
      hack_count++;
    }

    if ((hack_count + grow_count + weaken_count) % 50 === 0) {
      ns.tprint(`[${target}] H:${hack_count} G:${grow_count} W:${weaken_count} Evals:${eval_count}`);
    }
  }
}

