export async function main(ns) {
  const targets = ['foodnstuff','n00dles','sigma-cosmetics','joesguns','nectar-net','hong-fang-tea','harakiri-sushi'];
  let lastTarget = '';
  while(true) {
    let found = false;
    for(let t of targets) {
      try {
        if(!ns.hasRootAccess(t)) continue;
        if(ns.getServerRequiredHackingLevel(t) > ns.getHackingLevel()) continue;
        if(ns.getServerMaxMoney(t) <= 0) continue;
        if(t !== lastTarget) { ns.tprint(t); lastTarget = t; }
        found = true;
        let sec = ns.getServerSecurityLevel(t);
        let minSec = ns.getServerMinSecurityLevel(t);
        if(sec > minSec + 3) {
          await ns.weaken(t);
        } else {
          let mon = ns.getServerMoneyAvailable(t);
          let maxMon = ns.getServerMaxMoney(t);
          if(mon < maxMon * 0.75) {
            await ns.grow(t);
          } else {
            await ns.hack(t);
          }
        }
        break;
      } catch(e) {}
    }
    if(!found) await ns.sleep(1000);
  }
}

