  while (true) {
    for (let s of ['n00dles', 'foodnstuff', 'sigma-cosmetics', 'joesguns']) {
      if (ns.hasRootAccess(s) && ns.getRequiredHackingLevel(s) <= ns.getHackingLevel() && ns.getServerMaxMoney(s) > 0) {
