    if (!t) {
      await ns.sleep(2000);
      continue;
    }
    if (t !== last) {
      ns.tprint(t);
      last = t;
    }
    let sec = ns.getServerSecurityLevel(t);
    let minSec = ns.getServerMinSecurityLevel(t);
    if (sec > minSec + 3) await ns.weaken(t);
    else if (ns.getServerMoneyAvailable(t) < ns.getServerMaxMoney(t) * 0.75) await ns.grow(t);
    else await ns.hack(t);
  }
}

