export async function main(ns) {
  const target = 'n00dles';
  const openers = ['brutessh', 'ftpcrack', 'relaysmtp', 'httpworm', 'sqlinject'];

  // Root attempt: try openers if their .exe exists, then nuke
  for (const opener of openers) {
    if (ns.fileExists(opener + '.exe', 'home')) {
      ns[opener](target);
    }
  }
  if (ns.fileExists('NUKE.exe', 'home')) {
    ns.nuke(target);
  }

  // Infinite hack loop
  while (true) {
    if (ns.hasRootAccess(target)) {
      await ns.hack(target);
    } else {
      await ns.sleep(5000);
    }
  }
}

